-- 2055_platform_template_drafts_and_mobile_layout.sql
--
-- Rewrites the 29 built-in campaign templates (seeded by 0048, 0187, 0240 and
-- 0241, partly redacted by 1722) so a draft made from one is a real email for
-- the workspace that uses it, and so every design fits a phone.
--
-- What was wrong with the seeded rows:
--
--   * 24 templates declared the send-time unsubscribe placeholder as an
--     ordinary variable with a sample default (https://postwave.com/unsubscribe
--     or https://example.invalid/unsubscribe). Draft creation substituted every
--     default, so recipients got a link to a domain the sender does not control
--     and no working unsubscribe. The application now refuses to substitute
--     send-time tags at all; the variable entries are removed here so no client
--     offers them as editable fields.
--   * The sender was named through sample defaults: product = "Postwave",
--     founder/author = "Alex", reply-to = creator@example.invalid or
--     support@postwave.com, and "Postwave" was written into the copy of eight
--     designs. Those tags become the workspace tokens {{ brand_name }},
--     {{ sender_name }} and {{ reply_to_email }}, which draft creation fills
--     from the workspace's own settings.
--   * Recipient data was sample text: first names defaulted to "Friend" or
--     "Mira", an account email to mira@loomstack.io. Those become subscriber
--     tags ({{ first_name }}, {{ email }}) rendered per recipient; a first
--     name's default is now only the fallback for subscribers without one.
--   * Links pointed at app.postwave.com/postwave.com (both parked domains) or
--     at "#". Content links now have no default, so an unfilled link stays a
--     visible {{ tag }} in the draft; preference actions (mute, pause, keep,
--     stay gone) use the recipient's preference centre via {{ unsubscribe_url }}.
--   * Three legacy starters still carried their 0048 MJML after 0241 redesigned
--     their HTML, so drafts compiled a different design from the one previewed.
--     HTML is the single body now.
--   * Every design used fixed 600px tables and rendered 600-1036px wide on a
--     375px screen. Tables are now fluid (width:100%;max-width:600px), rules
--     drawn with characters clip instead of widening the layout, and each body
--     is a complete document whose <head> carries the viewport and a small
--     mobile stylesheet (Gmail honours <style> only there). Desktop rendering
--     is unchanged.
--
-- Each row is rewritten only while its body is still exactly the seeded body
-- (md5 below). If any built-in row has been edited out of band, the migration
-- stops rather than overwrite that edit; reconcile the row and re-run.
--
-- rollback-strategy: no-op - restoring the seeded content would reintroduce a foreign unsubscribe link and sample sender identities.

BEGIN;

WITH replacement (slug, previous_body_md5, subject, preview_text, description, body_html, variables) AS (
    VALUES
        -- Milestone Number Hero
        ('announcement-milestone-typographic', 'ee3c1e85bf1b45b8c73a6160c8bb47a1',
         $s${{ milestone_number }}$s$,
         $p$A number, a thank-you, and one thing we're doing about it.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Milestone Number Hero</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto;background-color:#FAF9F6;font-family:Georgia,'Times New Roman',serif;width:100%;max-width:600px;"><tr><td style="padding:32px 24px 16px 24px;text-align:center;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.2em;color:#8B7E68;text-transform:uppercase;">─── a small note from the team ───</div></td></tr><tr><td style="padding:0 24px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#F5E6D3;background-image:linear-gradient(135deg,#FDF4E3,#F5E6D3);border-radius:8px;"><tr><td align="center" valign="middle" style="height:200px;padding:40px 24px;text-align:center;"><div class="mw-hero" style="font-family:Georgia,'Times New Roman',serif;font-size:96px;line-height:100px;color:#1A1A1A;font-weight:600;letter-spacing:-0.04em;">{{ milestone_number }}</div><div style="margin-top:16px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;line-height:16px;color:#6B5F4A;letter-spacing:0.15em;text-transform:uppercase;font-weight:600;">{{ milestone_label }}</div></td></tr></table></td></tr><tr><td style="padding:24px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#FFFFFF;border-radius:8px;border:1px solid #EFE6D5;"><tr><td class="mw-px" style="padding:32px;"><p style="margin:0 0 20px 0;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1A1A1A;">When we started, we weren't sure anyone would notice. Today there are {{ milestone_number }} of you — and that still doesn't feel real. So before anything else, thank you. Genuinely.</p><p style="margin:0 0 24px 0;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1A1A1A;">A few weeks ago {{ customer_name }} sent us a note that's been pinned to the wall ever since. It's the kind of thing that decides what we work on next.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 24px 0;"><tr><td style="padding:8px 0 8px 20px;border-left:3px solid #C9A87A;"><p style="margin:0;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:18px;line-height:28px;color:#4A3F2E;">— {{ customer_quote }}</p><p style="margin:12px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.15em;color:#8B7E68;text-transform:uppercase;">{{ customer_name }}</p></td></tr></table><p style="margin:0 0 28px 0;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1A1A1A;">Here's what we're doing about it: we're spending the next quarter on the unglamorous things — the small frictions, the rough edges, the second-clicks that should be first-clicks. No new logos. Just better work for the people already here.</p><table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center" style="margin:0 auto;"><tr><td align="center" style="background-color:#1A1A1A;border-radius:999px;"><a href="{{ cta_url }}" style="display:inline-block;padding:16px 32px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;font-weight:600;color:#FAF9F6;text-decoration:none;letter-spacing:0.02em;">Reply or share the news →</a></td></tr></table><div style="margin-top:36px;padding-top:24px;border-top:1px solid #EFE6D5;"><p style="margin:0 0 4px 0;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:20px;line-height:24px;color:#4A3F2E;">With gratitude,</p><p style="margin:0;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:24px;line-height:28px;color:#1A1A1A;">{{ sender_name }}</p></div></td></tr></table></td></tr><tr><td style="padding:8px 24px 32px 24px;text-align:center;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.2em;color:#8B7E68;text-transform:uppercase;margin-bottom:12px;">▌▌▌</div><p style="margin:0;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:12px;line-height:18px;color:#8B7E68;">You're getting this because you're one of the {{ milestone_number }}.<br><a href="{{ unsubscribe_url }}" style="color:#6B5F4A;text-decoration:underline;">Unsubscribe</a></p></td></tr></table></body></html>$b$,
         $v$[{"name": "milestone_number", "label": "Numeral", "default": "10,000"}, {"name": "milestone_label", "label": "Label", "default": "READERS"}, {"name": "customer_quote", "label": "Quote", "default": "A milestone worth sharing."}, {"name": "customer_name", "label": "Who sent the note", "default": "one of our readers"}, {"name": "cta_url", "label": "Share URL"}]$v$::jsonb),
        -- Changelog-First Launch
        ('announcement-product-launch', 'ae77a995dfceff03332aacec0ba528c9',
         $s${{ brand_name }} {{ version }} shipped — here is what changed$s$,
         $p$Written like a changelog, not a press release. Three line items. One link.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Changelog-First Launch</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color:#FFFFFF;margin:0 auto;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:56px 48px 32px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#737373;font-weight:500;">{{ brand_name }}&nbsp;v{{ version }} &nbsp;/&nbsp; SHIPPED&nbsp;{{ ship_date }}</div></td></tr><tr><td class="mw-px" style="padding:0 48px 36px 48px;"><div class="mw-title" style="font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:32px;line-height:38px;font-weight:700;color:#111111;letter-spacing:-0.01em;">{{ headline }}</div></td></tr><tr><td class="mw-px" style="padding:0 48px 14px 48px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td valign="top" width="28" style="width:28px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:22px;font-weight:700;color:#15803D;">+</td><td valign="top" style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:22px;color:#1F2937;">{{ change_one }}</td></tr></table></td></tr><tr><td class="mw-px" style="padding:0 48px 14px 48px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td valign="top" width="28" style="width:28px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:22px;font-weight:700;color:#15803D;">+</td><td valign="top" style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:22px;color:#1F2937;">{{ change_two }}</td></tr></table></td></tr><tr><td class="mw-px" style="padding:0 48px 36px 48px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td valign="top" width="28" style="width:28px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:22px;font-weight:700;color:#B45309;">~</td><td valign="top" style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:22px;color:#1F2937;">{{ change_three }}</td></tr></table></td></tr><tr><td class="mw-px" style="padding:0 48px 32px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:22px;color:#D4D4D4;letter-spacing:0.05em;width:0;min-width:100%;overflow:hidden;white-space:nowrap;">────────────────────────────────────</div></td></tr><tr><td class="mw-px" style="padding:0 48px 32px 48px;"><div style="font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:26px;color:#1A1A1A;">{{ why_paragraph }}</div></td></tr><tr><td class="mw-px" style="padding:0 48px 56px 48px;"><a href="{{ changelog_url }}" style="font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:15px;line-height:22px;color:#111111;font-weight:600;text-decoration:underline;text-underline-offset:3px;">Read the full changelog &rarr;</a></td></tr><tr><td class="mw-px" style="padding:0 48px 24px 48px;border-top:1px solid #EAEAEA;"></td></tr><tr><td class="mw-px" style="padding:0 48px 48px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:18px;letter-spacing:0.12em;text-transform:uppercase;color:#A3A3A3;">{{ brand_name }} &nbsp;//&nbsp; BUILD&nbsp;{{ version }} &nbsp;//&nbsp; <a href="{{ unsubscribe_url }}" style="color:#A3A3A3;text-decoration:underline;">UNSUBSCRIBE</a></div></td></tr></table></body></html>$b$,
         $v$[{"name": "version", "label": "Version", "default": "2026.6"}, {"name": "ship_date", "label": "Ship date", "default": "June 3, 2026"}, {"name": "headline", "label": "Headline", "default": "Segments can now reference shared audiences across workspaces"}, {"name": "change_one", "label": "Add 1", "default": "Cross-workspace audience references in segment builder"}, {"name": "change_two", "label": "Add 2", "default": "Inline preview when picking a shared audience"}, {"name": "change_three", "label": "Change 1", "default": "Segment edits now show diff before save"}, {"name": "why_paragraph", "label": "Why we built it", "default": "Three customers asked, four engineers argued, one PM lost. We shipped the version the customers wanted."}, {"name": "changelog_url", "label": "Changelog URL"}]$v$::jsonb),
        -- Sunset with a Runway
        ('announcement-sunset-with-runway', '7a9eed989e040e1733a46b6d3fb3cd43',
         $s$We are sunsetting {{ feature }} on {{ sunset_date }}$s$,
         $p$Here is the date, the why, the runway, and a one-click export. We owe you all four.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Sunset with a Runway</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color:#FFFFFF;margin:0 auto;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:48px 48px 0 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#6B6B6B;">Deprecation notice &middot; {{ feature }}</td></tr><tr><td class="mw-px" style="padding:32px 48px 8px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#B45309;">Sunset date</td></tr><tr><td class="mw-px mw-hero" style="padding:0 48px 16px 48px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:88px;line-height:96px;font-weight:700;color:#111111;letter-spacing:-0.04em;">{{ sunset_date }}</td></tr><tr><td class="mw-px" style="padding:8px 48px 0 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#6B6B6B;">───</td></tr><tr><td class="mw-px" style="padding:24px 48px 8px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#6B6B6B;">Why</td></tr><tr><td class="mw-px" style="padding:0 48px 32px 48px;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:26px;color:#1A1A1A;">{{ why_paragraph }}</td></tr><tr><td class="mw-px" style="padding:0 48px 0 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#6B6B6B;">───</td></tr><tr><td class="mw-px" style="padding:24px 48px 16px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#6B6B6B;">Runway</td></tr><tr><td class="mw-px" style="padding:0 48px 4px 48px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;"><tr><td width="14" valign="top" style="width:14px;padding:6px 14px 6px 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:20px;color:#B45309;">&bull;</td><td valign="top" style="padding:6px 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:20px;color:#1A1A1A;letter-spacing:0.02em;">{{ milestone_one }}</td></tr><tr><td width="14" valign="top" style="width:14px;padding:6px 14px 6px 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:20px;color:#B45309;">&bull;</td><td valign="top" style="padding:6px 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:20px;color:#1A1A1A;letter-spacing:0.02em;">{{ milestone_two }}</td></tr><tr><td width="14" valign="top" style="width:14px;padding:6px 14px 6px 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:20px;color:#DC2626;">&bull;</td><td valign="top" style="padding:6px 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:20px;color:#111111;font-weight:600;letter-spacing:0.02em;">{{ milestone_three }}</td></tr></table></td></tr><tr><td class="mw-px" style="padding:24px 48px 0 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#6B6B6B;">───</td></tr><tr><td class="mw-px" style="padding:32px 48px 40px 48px;"><a href="{{ export_url }}" style="display:inline-block;background-color:#111111;color:#FFFFFF;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:15px;line-height:20px;font-weight:600;text-decoration:none;padding:16px 32px;border-radius:6px;letter-spacing:0.01em;">Export everything (1 click) &rarr;</a></td></tr><tr><td class="mw-px" style="padding:0 48px 24px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#6B6B6B;">───</td></tr><tr><td class="mw-px" style="padding:0 48px 8px 48px;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:16px;line-height:24px;color:#1A1A1A;">No spin. No pivot copy. We built it, it did not earn its keep, and we owe you the runway to leave clean.</td></tr><tr><td class="mw-px" style="padding:0 48px 48px 48px;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:16px;line-height:24px;color:#1A1A1A;">— {{ sender_name }}</td></tr><tr><td class="mw-px" style="padding:24px 48px 48px 48px;border-top:1px solid #E5E5E5;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:18px;letter-spacing:0.12em;text-transform:uppercase;color:#6B6B6B;">Deprecation notice &middot; {{ feature }} &middot; <a href="{{ unsubscribe_url }}" style="color:#6B6B6B;text-decoration:underline;">Unsubscribe</a></td></tr></table></body></html>$b$,
         $v$[{"name": "feature", "label": "Feature", "default": "Legacy Segment API v1"}, {"name": "sunset_date", "label": "Sunset date", "default": "AUG 31"}, {"name": "why_paragraph", "label": "Why", "default": "The legacy API is being replaced by a version with an explicit compatibility and migration contract."}, {"name": "milestone_one", "label": "Milestone 1", "default": "JUN 15 · v2 reaches feature parity"}, {"name": "milestone_two", "label": "Milestone 2", "default": "JUL 31 · v1 returns deprecation warnings"}, {"name": "milestone_three", "label": "Milestone 3", "default": "AUG 31 · v1 returns 410 Gone"}, {"name": "export_url", "label": "Export URL"}]$v$::jsonb),
        -- We Didn't Ship This
        ('announcement-we-didnt-ship', '11de6524e411de31e91e00a793ae8cf9',
         $s$We rebuilt {{ feature }}. Here's what we cut.$s$,
         $p$Three things didn't make it. We'll tell you exactly why.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>We Didn't Ship This</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><div style="background-color:#FAFAFA;padding:40px 20px;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto;background-color:#FFFFFF;border:1px solid #E5E5E5;border-radius:12px;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:48px 48px 16px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.1em;text-transform:uppercase;color:#737373;font-weight:600;">RELEASE&nbsp;&nbsp;{{ version }}</div></td></tr><tr><td class="mw-px" style="padding:8px 48px 24px 48px;"><h1 class="mw-display" style="margin:0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:42px;line-height:46px;color:#0A0A0A;font-weight:600;letter-spacing:-0.02em;">We rebuilt {{ feature }}.</h1></td></tr><tr><td class="mw-px" style="padding:0 48px 32px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;color:#A3A3A3;letter-spacing:0.05em;width:0;min-width:100%;overflow:hidden;white-space:nowrap;">───────────────────────────────────</div></td></tr><tr><td class="mw-px" style="padding:0 48px 16px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:#0A0A0A;font-weight:700;">TL;DR &nbsp;//&nbsp; WHAT SHIPPED</div></td></tr><tr><td class="mw-px" style="padding:0 48px 40px 48px;"><p style="margin:0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:17px;line-height:26px;color:#262626;">{{ feature }} is faster, calmer, and does less. We threw away the parts that nobody used and rebuilt the parts that everyone fought with. It now loads in under a second and stays out of your way until you need it.</p></td></tr><tr><td class="mw-px" style="padding:0 48px 24px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;letter-spacing:0.1em;text-transform:uppercase;color:#DC2626;font-weight:700;">▌ WHAT WE CUT</div></td></tr><tr><td class="mw-px" style="padding:0 48px 8px 48px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;"><tr><td valign="top" width="40" style="width:40px;padding:4px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#A3A3A3;font-weight:600;">01</td><td valign="top" style="padding:0 0 20px 0;"><div style="font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:17px;color:#737373;text-decoration:line-through;font-weight:500;">{{ cut_item_one }}</div><p style="margin:6px 0 0 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#404040;">It looked clever in a demo and nobody touched it in production. We measured six months of usage and the answer was honest enough to act on.</p></td></tr><tr><td colspan="2" style="padding:0 0 4px 0;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;color:#E5E5E5;letter-spacing:0.05em;width:0;min-width:100%;overflow:hidden;white-space:nowrap;">·······································</div></td></tr><tr><td valign="top" width="40" style="width:40px;padding:4px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#A3A3A3;font-weight:600;">02</td><td valign="top" style="padding:0 0 20px 0;"><div style="font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:17px;color:#737373;text-decoration:line-through;font-weight:500;">The settings panel inside the settings panel</div><p style="margin:6px 0 0 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#404040;">Two levels of nesting was one too many and we knew it. The five options that mattered are now in plain view. The rest are gone.</p></td></tr><tr><td colspan="2" style="padding:0 0 4px 0;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;color:#E5E5E5;letter-spacing:0.05em;width:0;min-width:100%;overflow:hidden;white-space:nowrap;">·······································</div></td></tr><tr><td valign="top" width="40" style="width:40px;padding:4px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#A3A3A3;font-weight:600;">03</td><td valign="top" style="padding:0 0 8px 0;"><div style="font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:17px;color:#737373;text-decoration:line-through;font-weight:500;">The onboarding tour with seven tooltips</div><p style="margin:6px 0 0 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#404040;">If the product needs seven tooltips to explain itself, the product is the problem. We rewrote the interface instead of the explanation.</p></td></tr></table></td></tr><tr><td class="mw-px" style="padding:24px 48px 8px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;color:#A3A3A3;letter-spacing:0.05em;width:0;min-width:100%;overflow:hidden;white-space:nowrap;">───────────────────────────────────</div></td></tr><tr><td class="mw-px" align="left" style="padding:24px 48px 12px 48px;"><a href="{{ cta_url }}" style="display:inline-block;background-color:#0A0A0A;color:#FFFFFF;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:15px;font-weight:600;text-decoration:none;padding:14px 28px;border-radius:999px;letter-spacing:0.01em;">Try {{ feature }} &rarr;</a></td></tr><tr><td class="mw-px" style="padding:0 48px 40px 48px;"><a href="{{ changelog_url }}" style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#737373;text-decoration:underline;text-underline-offset:3px;">Read the full changelog</a></td></tr><tr><td class="mw-px" style="padding:0 48px 16px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;color:#E5E5E5;letter-spacing:0.05em;">▌▌▌</div></td></tr><tr><td class="mw-px" style="padding:0 48px 48px 48px;"><p style="margin:0 0 4px 0;font-family:'Caveat',Georgia,serif;font-size:24px;line-height:28px;color:#0A0A0A;font-style:italic;">— the team</p><p style="margin:0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:13px;line-height:20px;color:#737373;">Built with fewer features. On purpose.</p></td></tr></table><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="margin:24px auto 0 auto;width:100%;max-width:600px;"><tr><td class="mw-px" align="center" style="padding:16px 48px;"><p style="margin:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:18px;color:#A3A3A3;letter-spacing:0.05em;">You're getting release notes because you use {{ brand_name }}.<br/><a href="{{ unsubscribe_url }}" style="color:#737373;text-decoration:underline;">Unsubscribe</a> &nbsp;·&nbsp; <a href="{{ changelog_url }}" style="color:#737373;text-decoration:underline;">All releases</a></p></td></tr></table></div></body></html>$b$,
         $v$[{"name": "version", "label": "Version", "default": "2026.6"}, {"name": "feature", "label": "Feature", "default": "the audience segment builder"}, {"name": "cut_item_one", "label": "First cut", "default": "Bulk re-segment on import"}, {"name": "cta_url", "label": "Try-it URL"}, {"name": "changelog_url", "label": "Changelog URL"}]$v$::jsonb),
