oard &rarr;</a></td></tr><tr><td style="padding:8px 28px 20px 28px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;color:#94A3B8;letter-spacing:0.1em;">Takes about 5 minutes &middot; opens to {{ metric_label }} view</td></tr><tr><td style="padding:0 28px 4px 28px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;color:#E2E8F0;letter-spacing:0.2em;"><div style="width:0;min-width:100%;overflow:hidden;white-space:nowrap;">&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;</div></td></tr><tr><td style="padding:16px 28px 24px 28px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:13px;line-height:20px;color:#64748B;"><a href="{{ unsubscribe_url }}" style="color:#0F172A;text-decoration:underline;font-weight:500;">Change which alerts you get</a><span style="color:#CBD5E1;padding:0 8px;">&middot;</span><a href="{{ unsubscribe_url }}" style="color:#0F172A;text-decoration:underline;font-weight:500;">Manage email preferences</a></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" style="padding:20px 16px 8px 16px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:12px;line-height:18px;color:#94A3B8;">You're receiving this anomaly alert because you turned it on in your {{ brand_name }} account.</td></tr><tr><td align="center" style="padding:4px 16px 24px 16px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:12px;color:#94A3B8;"><a href="{{ unsubscribe_url }}" style="color:#64748B;text-decoration:underline;">Unsubscribe</a></td></tr></table></td></tr></table></body></html>$b$,
