         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Day-Three Course Correction</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color:#FFFFFF;margin:0 auto;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:48px 48px 0 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:#737373;">DAY 3 OF 5</td></tr><tr><td class="mw-px mw-title" style="padding:18px 48px 0 48px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:28px;line-height:34px;font-weight:600;color:#111111;">{{ headline }}</td></tr><tr><td class="mw-px" style="padding:14px 48px 0 48px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;line-height:22px;color:#525252;">We took a look at where you are. Here is your status, and the one thing worth fixing today.</td></tr><tr><td class="mw-px" style="padding:32px 48px 0 48px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;border-top:1px solid #E5E5E5;border-bottom:1px solid #E5E5E5;"><tr><td width="50%" style="width:50%;padding:16px 16px 16px 0;vertical-align:top;border-right:1px solid #E5E5E5;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:18px;color:#15803D;letter-spacing:0.02em;">[x]</div><div style="margin-top:6px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;line-height:20px;color:#1F2937;">{{ done_item_one }}</div><div style="margin-top:4px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;color:#737373;letter-spacing:0.08em;text-transform:uppercase;">Complete</div></td><td width="50%" style="width:50%;padding:16px 0 16px 16px;vertical-align:top;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:18px;color:#15803D;letter-spacing:0.02em;">[x]</div><div style="margin-top:6px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;line-height:20px;color:#1F2937;">Account verified</div><div style="margin-top:4px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;color:#737373;letter-spacing:0.08em;text-transform:uppercase;">Complete</div></td></tr><tr><td width="50%" style="width:50%;padding:16px 16px 16px 0;vertical-align:top;border-top:1px solid #E5E5E5;border-right:1px solid #E5E5E5;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:18px;color:#B45309;letter-spacing:0.02em;">[ ]</div><div style="margin-top:6px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;line-height:20px;color:#1F2937;">{{ todo_item_one }}</div><div style="margin-top:4px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;color:#B45309;letter-