         $v$[{"name": "headline", "label": "Headline", "default": "Your domain is verified — your DKIM record is not"}, {"name": "done_item_one", "label": "Done 1", "default": "Workspace created"}, {"name": "todo_item_one", "label": "Todo 1", "default": "DKIM record published"}, {"name": "fix_paragraph", "label": "Fix copy", "default": "Add the DKIM TXT record below to your DNS — propagates in under an hour."}, {"name": "fix_snippet", "label": "Fix snippet", "default": "selector._domainkey  TXT  v=DKIM1; k=rsa; p=MIGfMA0GC..."}, {"name": "fix_url", "label": "Open setting URL"}]$v$::jsonb),
