         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Card-Grid Story Digest</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color:#F4F4F5;font-family:system-ui,-apple-system,Segoe UI,sans-serif;width:100%;max-width:600px;"><tr><td style="padding:32px 24px 8px 24px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.1em;text-transform:uppercase;color:#71717A;">THIS WEEK &nbsp;/&nbsp; {{ issue_date }}</td></tr><tr><td style="padding-top:10px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:24px;line-height:30px;font-weight:700;color:#18181B;letter-spacing:-0.01em;">5 things I&rsquo;m watching this week</td></tr><tr><td style="padding-top:6px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:22px;color:#52525B;">The shortlist: deliverability, AMP, sender rep, BIMI, and one I can&rsquo;t believe.</td></tr></table></td></tr><tr><td style="padding:24px 24px 0 24px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#FFFFFF;border:1px solid #E4E4E7;border-radius:14px;"><tr><td style="padding:22px 24px 22px 24px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;letter-spacing:0.12em;text-transform:uppercase;color:#0EA5E9;font-weight:600;">{{ card_one_eyebrow }}</div><div style="padding-top:10px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:18px;line-height:24px;font-weight:600;color:#18181B;letter-spacing:-0.01em;">{{ card_one_title }}</div><div style="padding-top:8px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:22px;color:#52525B;">Gmail and Yahoo quietly raised the bar again. The new spam thresholds mean even a 0.2% complaint rate can throttle delivery on big lists.</div><div style="padding-top:14px;"><a href="{{ card_one_url }}" style="font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:20px;font-weight:700;color:#0EA5E9;text-decoration:underline;">Read it &rarr;</a></div></td></tr></table></td></tr><tr><td style="padding:16px 24px 0 24px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#FFFFFF;border:1px solid #E4E4E7;border-radius:14px;"><tr><td style="padding:22px 24px 22px 24px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;letter-spacing:0.12em;text-transform:uppercase;color:#A855F7;font-weight:600;">TOOLING</div><div style="padding-top:10px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:18px;line-height:24px;font-weight:600;color:#18181B;letter-spacing:-0.01em;">AMP for Email is having a quiet renaissance</div><div style="padding-top:8px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:22px;color:#52525B;">Three ESPs shipped first-class AMP support this month. Inline forms, live carousels, dynamic pricing &mdash; without leaving the inbox.</div><div style="padding-top:14px;"><a href="{{ card_two_url }}" style="font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:20px;font-weight:700;color:#A855F7;text-decoration:underline;">Read it &rarr;</a></div></td></tr></table></td></tr><tr><td style="padding:16px 24px 0 24px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#FFFFFF;border:1px solid #E4E4E7;border-radius:14px;"><tr><td style="padding:22px 24px 22px 24px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;letter-spacing:0.12em;text-transform:uppercase;color:#F97316;font-weight:600;">OPINION &nbsp;&middot;&nbsp; #3</div><div style="padding-top:10px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:18px;line-height:24px;font-weight:600;color:#18181B;letter-spacing:-0.01em;">BIMI is a marketing channel now, and nobody told the marketers</div><div style="padding-top:8px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:22px;color:#52525B;">The logo-in-the-inbox spec was meant to fight spoofing. It&rsquo;s quietly become the most valuable 32x32 pixels in marketing. This is the wild one.</div><div style="padding-top:14px;"><a href="{{ card_three_url }}" style="font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:20px;font-weight:700;color:#F97316;text-decoration:underline;">Read it &rarr;</a></div></td></tr></table></td></tr><tr><td style="padding:28px 24px 12px 24px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.08em;color:#A1A1AA;width:0;min-width:100%;overflow:hidden;white-space:nowrap;">&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;</div></td></tr><tr><td style="padding:4px 24px 32px 24px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:12px;line-height:18px;color:#71717A;">You&rsquo;re reading issue {{ issue_date }} of the digest. Missed a week? <a href="{{ archive_url }}" style="color:#18181B;text-decoration:underline;font-weight:600;">Browse the archive &rarr;</a></td></tr><tr><td style="padding-top:10px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.06em;color:#A1A1AA;">Sent with care &middot; <a href="{{ unsubscribe_url }}" style="color:#71717A;text-decoration:underline;">Unsubscribe</a></td></tr></table></td></tr></table></body></html>$b$,
         $v$[{"name": "issue_date", "label": "Issue date", "default": "May 28"}, {"name": "card_one_eyebrow", "label": "Card 1 category", "default": "DELIVERABILITY"}, {"name": "card_one_title", "label": "Card 1 title", "default": "Gmail's new spam threshold is biting"}, {"name": "card_one_url", "label": "Card 1 link"}, {"name": "card_two_url", "label": "Card 2 link"}, {"name": "card_three_url", "label": "Card 3 link"}]$v$::jsonb),
        -- Editorial Masthead Essay
        ('newsletter-editorial-masthead', '63f3d330fc415f56633458027174e536',
         $s$the post i almost didn't send$s$,
         $p$On the thing nobody in our space wants to admit out loud.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Editorial Masthead Essay</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><div style="background-color:#F7F3EC;padding:32px 16px;font-family:Georgia,'Times New Roman',serif;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto;background-color:#FFFCF6;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:36px 44px 0 44px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td align="left" style="font-family:Georgia,'Times New Roman',serif;font-size:22px;line-height:26px;letter-spacing:0.04em;color:#1B1B1B;font-weight:400;">{{ brand_name }} <span style="color:#6B5F4A;">/</span> Dispatch</td><td align="right" style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;line-height:26px;color:#6B5F4A;letter-spacing:0.08em;">Issue No. {{ issue_number }}</td></tr></table></td></tr><tr><td class="mw-px" style="padding:14px 44px 0 44px;"><div style="border-top:1px solid #E4DCC8;height:1px;line-height:1px;font-size:1px;">&nbsp;</div></td></tr><tr><td class="mw-px" style="padding:22px 44px 0 44px;" align="left"><span style="display:inline-block;border:1px solid #C9BFA8;color:#6B5F4A;border-radius:999px;padding:5px 12px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:11px;letter-spacing:0.12em;text-transform:uppercase;">&#9711; {{ read_time }} read</span></td></tr><tr><td class="mw-px mw-title" style="padding:24px 44px 0 44px;font-family:Georgia,'Times New Roman',serif;font-size:34px;line-height:40px;color:#1B1B1B;letter-spacing:-0.01em;">{{ essay_title }}</td></tr><tr><td class="mw-px" style="padding:18px 44px 0 44px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;color:#A89B7C;letter-spacing:0.18em;">&mdash;&mdash;&mdash;&mdash; THE COLD OPEN</td></tr><tr><td class="mw-px" style="padding:14px 44px 0 44px;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:22px;line-height:30px;color:#1B1B1B;">{{ cold_open }}</td></tr><tr><td class="mw-px" style="padding:28px 44px 0 44px;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1B1B1B;">There's a post I almost didn't send. It sat in my drafts for nine days. I rewrote the opening eleven times. I asked a friend to read it. She said the quiet part too loud: <em>you're going to publish this anyway, so stop pretending you're deciding.</em><br><br>She was right. Most of the things we agonize over sending aren't really about the writing. They're about the small, embarrassing risk of being slightly more honest in public than we usually are. The risk of someone reading the line we underlined for ourselves and seeing the version of us that wrote it.</td></tr><tr><td class="mw-px" style="padding:24px 44px 0 44px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#FBF1E6;border-left:4px solid #C2410C;"><tr><td style="padding:18px 22px;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:18px;line-height:28px;color:#1B1B1B;">&ldquo;{{ pull_quote }}&rdquo;</td></tr></table></td></tr><tr><td class="mw-px" style="padding:24px 44px 0 44px;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1B1B1B;">The thing nobody in our space wants to admit out loud is that the polish is mostly a stalling tactic. The third edit isn't sharpening the argument; it's softening it. By the seventh, the post is shaped like everyone else's. By the ninth, it's safe enough that no one will remember reading it.<br><br>I'm not interested in writing the safe version anymore. I don't think you are either &mdash; otherwise you wouldn't be on a list called Dispatch, reading a 400-word essay on a Tuesday morning instead of the news. So here's the compromise I've made with myself, and it's the only editorial rule I follow now: <strong style="font-weight:600;">if it scares me a little to press send, it's probably the right one.</strong><br><br>This was one of those.</td></tr><tr><td class="mw-px" style="padding:30px 44px 0 44px;" align="center"><span style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:13px;color:#C9BFA8;letter-spacing:0.4em;">&#9642; &nbsp; &#9642; &nbsp; &#9642;</span></td></tr><tr><td class="mw-px" style="padding:24px 44px 0 44px;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1B1B1B;" align="left">I'd love to know which side of the draft folder you're on this week &mdash; the one you almost didn't send, or the one you wish you had.<br><br><a href="mailto:{{ reply_to_email }}" style="font-family:Georgia,'Times New Roman',serif;font-weight:700;font-size:17px;line-height:28px;color:#C2410C;text-decoration:underline;">Reply with your take &rarr;</a></td></tr><tr><td class="mw-px" style="padding:36px 44px 0 44px;"><div style="border-top:1px solid #E4DCC8;height:1px;line-height:1px;font-size:1px;">&nbsp;</div></td></tr><tr><td class="mw-px" style="padding:18px 44px 0 44px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td align="left" style="font-family:Georgia,'Times New Roman',serif;font-size:14px;line-height:20px;color:#1B1B1B;"><span style="font-style:italic;color:#6B5F4A;">Written by</span><br><strong style="font-weight:600;">{{ sender_name }}</strong></td><td align="right" style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;color:#6B5F4A;letter-spacing:0.14em;text-transform:uppercase;">{{ brand_name }}<br>Dispatch &middot; No. {{ issue_number }}</td></tr></table></td></tr><tr><td class="mw-px" style="padding:28px 44px 36px 44px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:18px;color:#A89B7C;letter-spacing:0.06em;" align="center">You're reading because you asked to. <a href="{{ unsubscribe_url }}" style="color:#6B5F4A;text-decoration:underline;">Unsubscribe</a> any time &mdash; no hard feelings, no follow-up sequence.</td></tr></table></div></body></html>$b$,
         $v$[{"name": "issue_number", "label": "Issue #", "default": "Issue 014"}, {"name": "read_time", "label": "Read time", "default": "4 min read"}, {"name": "essay_title", "label": "Essay title", "default": "The post I almost didn't send"}, {"name": "cold_open", "label": "Cold open", "default": "I've been wrong about open rates for two years."}, {"name": "pull_quote", "label": "Pull-quote", "default": "The metric we optimized made the product worse."}]$v$::jsonb),
        -- Margin-Notes Newsletter
        ('newsletter-margin-notes', '1fad07dcac6263082c694f10dd41e70b',
         $s${{ essay_title }}$s$,
         $p$An essay you can read in 4 minutes — or skim the margin notes in 40 seconds.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Margin-Notes Newsletter</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color:#FAF9F6;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:48px 40px 32px 40px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:#7A6F5C;">{{ sender_name }} &middot; {{ read_time }}</div></td></tr><tr><td class="mw-px" style="padding:0 40px 28px 40px;"><h1 class="mw-title" style="margin:0;font-family:Georgia,'Times New Roman',serif;font-size:30px;line-height:38px;color:#1A1A1A;font-weight:400;">{{ essay_title }}</h1></td></tr><tr><td class="mw-px" style="padding:0 40px 8px 40px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.18em;color:#B8AC95;">&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;</div></td></tr><tr><td class="mw-px" style="padding:24px 40px 0 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:520px;"><tr valign="top"><td class="mw-stack mw-stack-gap" width="65%" valign="top" style="padding:0 20px 0 0;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#2A2A2A;width:65%;"><p style="margin:0 0 20px 0;">There is a particular kind of attention the modern reader has lost &mdash; not the ability to focus, exactly, but the willingness to follow a single thought through three paragraphs before checking whether it pays off.</p><p style="margin:0 0 20px 0;">I have been thinking about this because of a notebook I found from 1987. The previous owner had written the body of an essay on the left page and, on the right, four words: <em>this is the turn.</em> A signal to her future self that the argument was about to pivot.</p><p style="margin:0 0 24px 0;">We used to read with a pencil. We used to argue with the margin. Now we scroll, and the margin is empty, and the argument loses.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 24px 0;width:100%;max-width:340px;"><tr><td style="padding:8px 0 8px 20px;border-left:3px solid #C9B68A;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:20px;line-height:30px;color:#4A3F2E;">{{ pull_quote }}</td></tr></table><p style="margin:0 0 20px 0;">So this newsletter is an experiment. The essay is on the left. The margin is on the right. If you have four minutes, read the essay. If you have forty seconds, skim the notes and you will still leave with the shape of the idea.</p><p style="margin:0;">Either way &mdash; thank you for the attention. It is the only currency I trust.</p></td><td class="mw-stack" width="35%" valign="top" style="width:35%;"><table class="mw-full" role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;background-color:#FFFFFF;border:1px solid #E8E0CC;margin-bottom:12px;"><tr><td style="padding:16px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:#9A8C6E;margin-bottom:8px;">Note 01</div><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:19px;color:#2A2A2A;">{{ margin_one }}</div></td></tr></table><table class="mw-full" role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;background-color:#FFFFFF;border:1px solid #E8E0CC;margin-bottom:12px;"><tr><td style="padding:16px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:#9A8C6E;margin-bottom:8px;">Note 02</div><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:19px;color:#2A2A2A;">{{ margin_two }}</div></td></tr></table><table class="mw-full" role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;background-color:#FFFFFF;border:1px solid #E8E0CC;"><tr><td style="padding:16px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:#9A8C6E;margin-bottom:8px;">Note 03</div><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:19px;color:#2A2A2A;">{{ margin_three }}</div></td></tr></table></td></tr></table></td></tr><tr><td class="mw-px" style="padding:40px 40px 16px 40px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.18em;color:#B8AC95;">&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;</div></td></tr><tr><td class="mw-px" style="padding:0 40px 48px 40px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:#7A6F5C;line-height:18px;"><a href="{{ archive_url }}" style="color:#7A6F5C;text-decoration:none;">Read in archive</a>  &nbsp;/&nbsp;  <a href="{{ unsubscribe_url }}" style="color:#7A6F5C;text-decoration:none;">Unsubscribe</a></div></td></tr></table></body></html>$b$,
         $v$[{"name": "essay_title", "label": "Essay title", "default": "The Tuesday problem"}, {"name": "read_time", "label": "Read time", "default": "4 min"}, {"name": "margin_one", "label": "Margin 1", "default": "Many B2B sends cluster on weekday mornings"}, {"name": "margin_two", "label": "Margin 2", "default": "Measure delivery and engagement before changing schedule"}, {"name": "margin_three", "label": "Margin 3", "default": "Compare a controlled alternate send window"}, {"name": "pull_quote", "label": "Pull-quote", "default": "The day everyone sends may not be your best send time."}]$v$::jsonb),
        -- One-Link Roundup
        ('newsletter-one-link', '0fe0431908d654d52fbfb3fc9e60990f',
         $s$One link this week. Just this one.$s$,
