         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Quiet-Exit Re-engagement</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto;background-color:#FAFAF7;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:56px 48px 24px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#737373;">List hygiene notice</div></td></tr><tr><td class="mw-px" style="padding:0 48px 32px 48px;"><h1 class="mw-title" style="margin:0;font-family:Georgia,'Times New Roman',serif;font-size:28px;line-height:36px;font-weight:400;color:#1A1A1A;letter-spacing:-0.01em;">We will quietly remove you from {{ list_name }} in {{ days_remaining }} days.</h1></td></tr><tr><td class="mw-px" style="padding:0 48px 20px 48px;"><p style="margin:0;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:16px;line-height:26px;color:#3A3A3A;">Hi {{ first_name }} — our records show {{ last_open_phrase }}. That's a long time, and we'd rather not crowd an inbox that isn't using us. So in {{ days_remaining }} days we'll take ourselves off your list automatically.</p></td></tr><tr><td class="mw-px" style="padding:0 48px 36px 48px;"><p style="margin:0;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:16px;line-height:26px;color:#3A3A3A;">If you'd like to stay, tap the button below once. If you'd rather not, you don't need to do anything — silence is a perfectly good answer here.</p></td></tr><tr><td class="mw-px" align="left" style="padding:0 48px 20px 48px;"><a href="{{ unsubscribe_url }}" style="display:inline-block;padding:16px 32px;background-color:#1A1A1A;color:#FAFAF7;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:15px;line-height:20px;font-weight:600;text-decoration:none;border-radius:6px;letter-spacing:0.01em;">Keep me on the list &rarr;</a></td></tr><tr><td class="mw-px" style="padding:0 48px 56px 48px;"><a href="{{ unsubscribe_url }}" style="font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;line-height:22px;color:#737373;text-decoration:underline;text-underline-offset:3px;">Or do nothing &mdash; also fine.</a></td></tr><tr><td class="mw-px" align="center" style="padding:0 48px 40px 48px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:20px;color:#A8A8A8;letter-spacing:0.4em;">*&nbsp;&nbsp;*&nbsp;&nbsp;*</div></td></tr><tr><td class="mw-px" style="padding:0 48px 24px 48px;"><p style="margin:0;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:13px;line-height:22px;color:#737373;">Questions, complaints, or a kind word? Reply to <a href="mailto:{{ reply_to_email }}" style="color:#3A3A3A;text-decoration:underline;text-underline-offset:2px;">{{ reply_to_email }}</a> and a person will read it.</p></td></tr><tr><td class="mw-px" style="padding:0 48px 56px 48px;border-top:1px solid #E8E6DF;"><div style="padding-top:24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:18px;letter-spacing:0.08em;color:#A8A8A8;">List: {{ list_name }}<br>Auto-prune in {{ days_remaining }} days<br><a href="{{ unsubscribe_url }}" style="color:#737373;text-decoration:underline;text-underline-offset:2px;">Unsubscribe now &rarr;</a></div></td></tr></table></body></html>$b$,
         $v$[{"name": "first_name", "label": "First name", "default": "there"}, {"name": "days_remaining", "label": "Days until prune", "default": "14"}, {"name": "last_open_phrase", "label": "Last open phrase", "default": "You haven't opened in about four months"}, {"name": "list_name", "label": "List name", "default": "our newsletter"}]$v$::jsonb),
        -- Letter From Future Self
        ('re-engagement-letter-from-future-self', '48ea0d85108314d3adb3a4598f597bca',
         $s$A short letter from the version of you who came back$s$,
         $p$Not a discount. Not a guilt trip. A two-paragraph letter, then your choice.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Letter From Future Self</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color:#FAF9F6;margin:0 auto;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:56px 56px 24px 56px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.22em;text-transform:uppercase;color:#8A8578;">A Letter &middot; Not From Us</td></tr><tr><td class="mw-px mw-title" style="padding:8px 56px 28px 56px;font-family:Georgia,'Times New Roman',serif;font-size:28px;font-style:italic;line-height:1.3;color:#2A2A2A;">Dear {{ first_name }},</td></tr><tr><td class="mw-px" style="padding:0 56px 24px 56px;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;font-style:italic;color:#2A2A2A;">{{ paragraph_one }}</td></tr><tr><td class="mw-px" style="padding:0 56px 36px 56px;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;font-style:italic;color:#2A2A2A;">{{ paragraph_two }}</td></tr><tr><td class="mw-px" style="padding:0 56px 8px 56px;font-family:Georgia,'Times New Roman',serif;font-size:20px;font-style:italic;line-height:1.4;color:#2A2A2A;">Future you</td></tr><tr><td class="mw-px" align="center" style="padding:40px 56px 40px 56px;font-family:Georgia,'Times New Roman',serif;font-size:18px;letter-spacing:0.4em;color:#B8B2A3;">*&nbsp;&nbsp;*&nbsp;&nbsp;*</td></tr><tr><td class="mw-px" align="center" style="padding:0 56px 16px 56px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center" style="margin:0 auto;"><tr><td style="padding:14px 24px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;line-height:1.4;color:#1A1A1A;"><a href="{{ come_back_url }}" style="color:#1A1A1A;text-decoration:underline;text-underline-offset:4px;font-weight:500;">come back</a></td><td style="padding:14px 8px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;color:#B8B2A3;">&nbsp;</td><td style="padding:14px 24px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;line-height:1.4;color:#1A1A1A;"><a href="{{ unsubscribe_url }}" style="color:#1A1A1A;text-decoration:underline;text-underline-offset:4px;font-weight:500;">stay gone</a></td></tr></table></td></tr><tr><td class="mw-px" style="padding:48px 56px 56px 56px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:#9A9486;line-height:1.6;">Either answer is a good one.<br /><a href="{{ unsubscribe_url }}" style="color:#9A9486;text-decoration:underline;">Unsubscribe</a></td></tr></table></body></html>$b$,
         $v$[{"name": "first_name", "label": "First name", "default": "friend"}, {"name": "paragraph_one", "label": "Letter para 1", "default": "I almost deleted that email too. The first thing I did when I came back was rebuild the segment we had been arguing about — it took 4 minutes."}, {"name": "paragraph_two", "label": "Letter para 2", "default": "We are still here. The product got quieter and better. Come see for yourself, or don't — both are fine."}, {"name": "come_back_url", "label": "Come back URL"}]$v$::jsonb),
        -- Pause-Or-Leave Choice
        ('re-engagement-pause-choice', '87ae92c646350a1515dbf5d3d6d7b7d4',
         $s$Before we stop emailing you$s$,
         $p$Three buttons. No groveling. Pick what's actually fair.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Pause-Or-Leave Choice</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><!-- re-engagement-pause-choice --><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto;background-color:#FFFFFF;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:56px 40px 24px 40px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.1em;text-transform:uppercase;color:#737373;font-weight:600;">Account &middot; {{ email }}</div></td></tr><tr><td class="mw-px" style="padding:0 40px 28px 40px;"><h1 class="mw-title" style="margin:0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:32px;line-height:36px;font-weight:600;color:#0A0A0A;letter-spacing:-0.01em;">Before we stop emailing you</h1></td></tr><tr><td class="mw-px" style="padding:0 40px 32px 40px;"><p style="margin:0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:16px;line-height:26px;color:#404040;">It's been {{ days_inactive }} days since you last opened one of our emails. That's a clear signal, and we respect it. Rather than keep landing in your inbox uninvited, we'd like you to choose what happens next.</p></td></tr><tr><td class="mw-px" style="padding:0 40px 16px 40px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.1em;text-transform:uppercase;color:#737373;font-weight:600;">─── What changed</div></td></tr><tr><td class="mw-px" style="padding:0 40px 32px 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;border-top:1px solid #E5E5E5;border-bottom:1px solid #E5E5E5;"><tr><td style="padding:14px 0 14px 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#0A0A0A;border-bottom:1px solid #E5E5E5;"><span style="display:inline-block;width:24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#737373;">01</span>{{ shipped_one }}</td></tr><tr><td style="padding:14px 0 14px 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#0A0A0A;border-bottom:1px solid #E5E5E5;"><span style="display:inline-block;width:24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#737373;">02</span>Faster sending, cleaner deliverability reports, fewer false positives.</td></tr><tr><td style="padding:14px 0 14px 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#0A0A0A;"><span style="display:inline-block;width:24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#737373;">03</span>Granular frequency controls so you hear from us less, not more.</td></tr></table></td></tr><tr><td class="mw-px" style="padding:0 40px 12px 40px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.1em;text-transform:uppercase;color:#737373;font-weight:600;">─── Pick what's fair</div></td></tr><tr><td class="mw-px" style="padding:0 40px 12px 40px;" align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:360px;margin:0 auto;"><tr><td align="center" style="padding:0 0 12px 0;"><a href="{{ unsubscribe_url }}" style="display:block;width:100%;max-width:360px;box-sizing:border-box;padding:14px 24px;background-color:#0A0A0A;color:#FFFFFF;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:16px;line-height:20px;font-weight:600;text-align:center;text-decoration:none;border-radius:999px;border:1.5px solid #0A0A0A;">Pause emails for a while</a></td></tr><tr><td align="center" style="padding:0 0 12px 0;"><a href="{{ unsubscribe_url }}" style="display:block;width:100%;max-width:360px;box-sizing:border-box;padding:14px 24px;background-color:#FFFFFF;color:#0A0A0A;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:16px;line-height:20px;font-weight:600;text-align:center;text-decoration:none;border-radius:999px;border:1.5px solid #0A0A0A;">Keep me subscribed</a></td></tr><tr><td align="center" style="padding:0 0 0 0;"><a href="{{ unsubscribe_url }}" style="display:block;width:100%;max-width:360px;box-sizing:border-box;padding:14px 24px;background-color:#FFFFFF;color:#737373;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:16px;line-height:20px;font-weight:600;text-align:center;text-decoration:none;border-radius:999px;border:1.5px solid #D4D4D4;">Unsubscribe now</a></td></tr></table></td></tr><tr><td class="mw-px" style="padding:24px 40px 32px 40px;" align="center"><p style="margin:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;line-height:18px;color:#737373;text-align:center;">No choice is wrong. We'll honor it immediately.</p></td></tr><tr><td class="mw-px" style="padding:0 40px 24px 40px;"><div style="height:1px;line-height:1px;font-size:0;background-color:#E5E5E5;">&nbsp;</div></td></tr><tr><td class="mw-px" style="padding:0 40px 48px 40px;" align="center"><p style="margin:0 0 8px 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:12px;line-height:18px;color:#A3A3A3;text-align:center;">You're receiving this because you subscribed {{ days_inactive }}+ days ago.</p><p style="margin:0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:12px;line-height:18px;color:#A3A3A3;text-align:center;">Prefer to leave now? <a href="{{ unsubscribe_url }}" style="color:#737373;text-decoration:underline;">Unsubscribe in one click</a>.</p></td></tr></table></body></html>$b$,
         $v$[{"name": "days_inactive", "label": "Days inactive", "default": "90"}, {"name": "shipped_one", "label": "Shipped 1", "default": "A new audience builder"}]$v$::jsonb),
        -- Export Ready with Half-Life
        ('transactional-export-ready', '3558f35d6fa530a022892e743f6a807b',
         $s$Your export is ready — deletes in {{ ttl_hours }}h$s$,
         $p$Download link, file size, SHA-256, and a half-life timer. That is the whole email.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Export Ready with Half-Life</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color:#FFFFFF;margin:0 auto;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:48px 48px 24px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#6B6B66;">EXPORT READY &middot; JOB {{ job_id }}</td></tr><tr><td class="mw-px" style="padding:0 48px 32px 48px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:26px;line-height:32px;font-weight:600;color:#111111;letter-spacing:-0.01em;">{{ headline }}</td></tr><tr><td class="mw-px" style="padding:0 48px 0 48px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;background-color:#F4F4F0;border-radius:4px;"><tr><td style="padding:24px 24px 8px 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;"><span style="display:inline-block;width:90px;color:#6B6B66;letter-spacing:0.08em;">FILE</span><span style="color:#111111;">&middot; {{ file_name }}</span></td></tr><tr><td style="padding:0 24px 0 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;"><span style="display:inline-block;width:90px;color:#6B6B66;letter-spacing:0.08em;">SIZE</span><span style="color:#111111;">&middot; {{ file_size }}</span></td></tr><tr><td style="padding:0 24px 0 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;"><span style="display:inline-block;width:90px;color:#6B6B66;letter-spacing:0.08em;">ROWS</span><span style="color:#111111;">&middot; {{ row_count }}</span></td></tr><tr><td style="padding:0 24px 0 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;word-break:break-all;"><span style="display:inline-block;width:90px;color:#6B6B66;letter-spacing:0.08em;vertical-align:top;">SHA-256</span><span style="color:#111111;">&middot; {{ sha_hash }}</span></td></tr><tr><td style="padding:0 24px 24px 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;"><span style="display:inline-block;width:90px;color:#6B6B66;letter-spacing:0.08em;">EXPIRES</span><span style="color:#111111;">&middot; {{ expires_at }}</span></td></tr></table></td></tr><tr><td class="mw-px" style="padding:24px 48px 8px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#6B6B66;">HALF-LIFE</td></tr><tr><td class="mw-px mw-display" style="padding:0 48px 32px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:56px;line-height:60px;font-weight:600;color:#111111;letter-spacing:-0.02em;">{{ ttl_hours }}h</td></tr><tr><td class="mw-px" style="padding:0 48px 40px 48px;"><a href="{{ download_url }}" style="display:inline-block;background-color:#111111;color:#FFFFFF;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;line-height:20px;font-weight:600;text-decoration:none;padding:16px 28px;border-radius:6px;letter-spacing:0.01em;">Download CSV &rarr;</a></td></tr><tr><td class="mw-px" style="padding:0 48px 32px 48px;font-family:Georgia,'Times New Roman',serif;font-size:12px;line-height:18px;font-style:italic;color:#6B6B66;">Link signed for your IP only. Deleted automatically.</td></tr><tr><td class="mw-px" style="padding:24px 48px 48px 48px;border-top:1px solid #E8E8E2;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:12px;line-height:18px;color:#6B6B66;">Questions about this export? Reply to <a href="mailto:{{ reply_to_email }}" style="color:#111111;text-decoration:underline;">{{ reply_to_email }}</a>.</td></tr></table></body></html>$b$,
         $v$[{"name": "job_id", "label": "Job ID", "default": "exp_01HZQ8K"}, {"name": "headline", "label": "Headline", "default": "Your subscriber export is ready"}, {"name": "file_name", "label": "File name", "default": "subscribers-2026-06-03.csv"}, {"name": "file_size", "label": "File size", "default": "14.2 MB"}, {"name": "row_count", "label": "Row count", "default": "124,308"}, {"name": "sha_hash", "label": "SHA-256", "default": "7a3f9c1d...e1c2"}, {"name": "ttl_hours", "label": "TTL hours", "default": "24"}, {"name": "expires_at", "label": "Expires at", "default": "2026-06-04 09:14 UTC"}, {"name": "download_url", "label": "Download URL"}]$v$::jsonb),
