ize:14px;line-height:20px;color:#6B7280;" width="45%">Last sign-in</td><td height="44" align="right" style="height:44px;padding:0 4px;border-bottom:1px solid #E5E7EB;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:20px;color:#111827;font-variant-numeric:tabular-nums;">{{ last_signin }}</td></tr><tr><td height="44" style="height:44px;padding:0 4px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:20px;color:#6B7280;" width="45%">Last password change</td><td height="44" align="right" style="height:44px;padding:0 4px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:20px;color:#111827;font-variant-numeric:tabular-nums;">{{ last_password_change }}</td></tr></table><p style="margin:0 0 28px 0;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:22px;color:#374151;">Was this you? If something looks off, lock your account now.</p><p style="margin:0 0 28px 0;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:20px;color:#DC2626;font-weight:700;"><a href="{{ security_url }}" style="color:#DC2626;text-decoration:underline;font-weight:700;">I didn't ask for this &rarr;</a></p><p style="margin:0 0 10px 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;line-height:16px;color:#9CA3AF;letter-spacing:0.02em;width:0;min-width:100%;overflow:hidden;white-space:nowrap;">─────────────────────────────</p><p style="margin:0;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:12px;line-height:18px;color:#6B7280;">Need help? Just reply to this email and our support team will get back to you. We never ask for your password.</p></td></tr></table></td></tr></table></body></html>$b$,
