font-size:16px;line-height:24px;color:#1A1A1A;">Something off? Reply to this email or write to <a href="mailto:{{ reply_to_email }}" style="color:#1A1A1A;text-decoration:underline;">{{ reply_to_email }}</a> &mdash; a real person reads every message.</td></tr><tr><td style="padding:0 28px 24px 28px;"><a href="mailto:{{ reply_to_email }}" style="display:inline-block;padding:14px 28px;background-color:#1A1A1A;color:#FAF7F0;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px;font-weight:600;line-height:20px;text-decoration:none;border-radius:6px;">Email support</a></td></tr></table></td></tr><tr><td class="mw-px" style="padding:0 48px 40px 48px;border-top:1px solid #E5E5E5;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;"><tr><td style="padding:20px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:10px;line-height:16px;letter-spacing:0.12em;text-transform:uppercase;color:#A3A3A3;">Transactional receipt &middot; Order {{ order_id }}</td></tr></table></td></tr></table></body></html>$b$,
         $v$[{"name": "order_id", "label": "Order ID", "default": "ORD-2026-04812"}, {"name": "item_one_label", "label": "Item 1", "default": "Growth plan · monthly"}, {"name": "item_one_amount", "label": "Item 1 amount", "default": "$79.00"}, {"name": "tax_amount", "label": "Tax", "default": "$6.32"}, {"name": "total_amount", "label": "Total", "default": "$85.32"}, {"name": "next_step_one", "label": "Next step 1", "default": "TODAY · Confirmation queued · 2 min"}, {"name": "next_step_two", "label": "Next step 2", "default": "TOMORROW · Invoice PDF emailed"}, {"name": "next_step_three", "label": "Next step 3", "default": "MONTHLY · Auto-renew on the 3rd"}]$v$::jsonb),
