         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>New-Device Security Alert</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color:#FFFFFF;margin:0 auto;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:48px 48px 0 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#737373;">SECURITY EVENT &middot; {{ event_id }}</td></tr><tr><td class="mw-px" style="padding:20px 48px 0 48px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:24px;line-height:32px;font-weight:600;color:#111111;">New sign-in on {{ device_label }}</td></tr><tr><td class="mw-px" style="padding:16px 48px 0 48px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:15px;line-height:24px;color:#404040;">Hi {{ first_name }} — we recorded a new authenticated session on your account. Review the fingerprint below.</td></tr><tr><td class="mw-px" style="padding:28px 48px 0 48px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#F4F4F0;"><tr><td style="padding:24px 24px 8px 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#737373;">FINGERPRINT</td></tr><tr><td style="padding:8px 24px 0 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;"><span style="color:#737373;">DEVICE&nbsp;&nbsp;&nbsp;</span>{{ device_label }}</td></tr><tr><td style="padding:0 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;"><span style="color:#737373;">BROWSER&nbsp;&nbsp;</span>{{ browser }}</td></tr><tr><td style="padding:0 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;"><span style="color:#737373;">IP&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>{{ ip_rounded }}</td></tr><tr><td style="padding:0 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;"><span style="color:#737373;">LOCATION&nbsp;</span>{{ coarse_location }}</td></tr><tr><td style="padding:0 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;"><span style="color:#737373;">ASN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>{{ asn }}</td></tr><tr><td style="padding:0 24px 24px 24px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;line-height:22px;color:#111111;"><span style="color:#737373;">AT&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>{{ timestamp }}</td></tr></table></td></tr><tr><td class="mw-px" style="padding:32px 48px 0 48px;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:16px;line-height:24px;color:#404040;">If this was you, ignore.</td></tr><tr><td class="mw-px" style="padding:24px 48px 0 48px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:15px;line-height:24px;color:#404040;">If it wasn't, one tap signs that session out and rotates the API token tied to it.</td></tr><tr><td class="mw-px" style="padding:28px 48px 0 48px;"><a href="{{ revoke_url }}" style="display:inline-block;background-color:#DC2626;color:#FFFFFF;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:15px;line-height:20px;font-weight:600;text-decoration:none;padding:16px 32px;border-radius:999px;">Revoke + rotate token &rarr;</a></td></tr><tr><td class="mw-px" style="padding:20px 48px 0 48px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:12px;line-height:18px;color:#737373;"><a href="{{ sessions_url }}" style="color:#737373;text-decoration:underline;">View sessions &rarr;</a></td></tr><tr><td class="mw-px" style="padding:40px 48px 16px 48px;border-top:1px solid #E5E5E5;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#737373;">&nbsp;</td></tr><tr><td class="mw-px" style="padding:0 48px 48px 48px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:12px;line-height:18px;color:#737373;">This is a security notification from {{ brand_name }}. Reply to this email if you need help from support — a human will respond.</td></tr></table></body></html>$b$,
         $v$[{"name": "event_id", "label": "Event ID", "default": "sec_01HZQ9A"}, {"name": "first_name", "label": "First name", "default": "there"}, {"name": "device_label", "label": "Device", "default": "MacBook Pro · macOS 14.5"}, {"name": "browser", "label": "Browser", "default": "Safari 17.5"}, {"name": "ip_rounded", "label": "IP rounded", "default": "203.0.113.x"}, {"name": "coarse_location", "label": "Location", "default": "Bangalore, IN (approx)"}, {"name": "asn", "label": "ASN", "default": "AS15169 Google LLC"}, {"name": "timestamp", "label": "Timestamp", "default": "2026-06-03 09:14 IST"}, {"name": "revoke_url", "label": "Revoke URL"}, {"name": "sessions_url", "label": "Sessions URL"}]$v$::jsonb),
