        ('welcome-day-one-cohort', 'be89d977d722ae8779e7b3e8a89acb66',
         $s$Day 1 of {{ brand_name }}$s$,
         $p$Here's the 5-day plan, and the one thing to do in the next 90 seconds.$p$,
         $d$Linear-style 'Day 1 of your product' welcome framing onboarding as a cohort journey with a visible 5-day roadmap and only one 90-second action for today.$d$,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Day One Cohort Welcome</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><div style="background-color:#FAFAFA;padding:48px 16px;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto;background-color:#FAFAFA;width:100%;max-width:600px;"><tr><td align="left" style="padding:0 4px 20px 4px;"><span style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;color:#6B6B6B;letter-spacing:0.12em;text-transform:uppercase;">{{ brand_name }} &nbsp;&middot;&nbsp; onboarding</span></td></tr><tr><td class="mw-px" style="background-color:#FFFFFF;border:1px solid #ECECEC;border-radius:12px;padding:40px 40px 32px 40px;"><p style="margin:0 0 18px 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;line-height:16px;color:#6B6B6B;letter-spacing:0.08em;text-transform:uppercase;">DAY 01 / 05</p><h1 class="mw-title" style="margin:0 0 16px 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:36px;line-height:40px;color:#0A0A0A;font-weight:600;letter-spacing:-0.02em;">Day 1 of {{ brand_name }}</h1><p style="margin:0 0 28px 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#3A3A3A;">Hey {{ first_name }} &mdash; welcome aboard. Over the next five days we&rsquo;ll walk you through {{ brand_name }} one small step at a time. No firehose. Just one focused thing per day, starting with a 90-second tour right now.</p><p style="margin:0 0 12px 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;color:#6B6B6B;letter-spacing:0.08em;text-transform:uppercase;">The 5-day plan</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;border-top:1px solid #ECECEC;margin:0 0 32px 0;"><tr><td width="56" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#0A0A0A;">01</td><td valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0 12px 0 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:14px;line-height:20px;color:#0A0A0A;font-weight:500;">{{ day_one_task }}</td><td align="right" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;"><span style="display:inline-block;background-color:#0A0A0A;color:#FFFFFF;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;letter-spacing:0.08em;text-transform:uppercase;padding:6px 12px;border-radius:999px;">today</span></td></tr><tr><td width="56" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#6B6B6B;">02</td><td valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0 12px 0 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:14px;line-height:20px;color:#3A3A3A;">Connect your first data source</td><td align="right" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;"><span style="display:inline-block;background-color:transparent;border:1px solid #D4D4D4;color:#6B6B6B;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;letter-spacing:0.08em;text-transform:uppercase;padding:5px 11px;border-radius:999px;">tue</span></td></tr><tr><td width="56" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#6B6B6B;">03</td><td valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0 12px 0 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:14px;line-height:20px;color:#3A3A3A;">Build a segment and a list</td><td align="right" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;"><span style="display:inline-block;background-color:transparent;border:1px solid #D4D4D4;color:#6B6B6B;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;letter-spacing:0.08em;text-transform:uppercase;padding:5px 11px;border-radius:999px;">wed</span></td></tr><tr><td width="56" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#6B6B6B;">04</td><td valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0 12px 0 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:14px;line-height:20px;color:#3A3A3A;">Ship your first campaign</td><td align="right" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;"><span style="display:inline-block;background-color:transparent;border:1px solid #D4D4D4;color:#6B6B6B;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;letter-spacing:0.08em;text-transform:uppercase;padding:5px 11px;border-radius:999px;">thu</span></td></tr><tr><td width="56" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#6B6B6B;">05</td><td valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0 12px 0 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:14px;line-height:20px;color:#3A3A3A;">Automate a 3-step journey</td><td align="right" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;"><span style="display:inline-block;background-color:transparent;border:1px solid #D4D4D4;color:#6B6B6B;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;letter-spacing:0.08em;text-transform:uppercase;padding:5px 11px;border-radius:999px;">fri</span></td></tr></table><p style="margin:0 0 8px 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;color:#6B6B6B;letter-spacing:0.08em;text-transform:uppercase;">Next 90 seconds</p><p style="margin:0 0 24px 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:15px;line-height:22px;color:#0A0A0A;">Take the guided tour. It&rsquo;s the fastest way to feel oriented before tomorrow&rsquo;s step.</p><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 8px 0;"><tr><td align="center" style="border-radius:999px;background-color:#0A0A0A;"><a href="{{ tour_url }}" style="display:inline-block;padding:14px 28px;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:14px;line-height:18px;color:#FFFFFF;font-weight:600;text-decoration:none;border-radius:999px;letter-spacing:-0.005em;">Take the 90-second tour &rarr;</a></td></tr></table><p style="margin:24px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;color:#9A9A9A;letter-spacing:0.04em;">&mdash;&mdash;&mdash; you&rsquo;ll hear from us again tomorrow at the same time.</p></td></tr><tr><td align="center" style="padding:24px 16px 8px 16px;"><p style="margin:0 0 6px 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:12px;line-height:18px;color:#6B6B6B;">Too much, too fast? <a href="{{ unsubscribe_url }}" style="color:#0A0A0A;text-decoration:underline;">Choose which emails you get</a>, and we&rsquo;ll follow your lead.</p></td></tr><tr><td align="center" style="padding:0 16px 24px 16px;"><p style="margin:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;color:#9A9A9A;letter-spacing:0.04em;">{{ brand_name }} &middot; <a href="{{ unsubscribe_url }}" style="color:#9A9A9A;text-decoration:underline;">unsubscribe</a></p></td></tr></table></div></body></html>$b$,
         $v$[{"name": "first_name", "label": "First name", "default": "there"}, {"name": "tour_url", "label": "Tour URL"}, {"name": "day_one_task", "label": "Today's task", "default": "Connect your sending domain"}]$v$::jsonb),
