         $p$No tour. No checklist. One sentence, one action, then we get out of your way.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>First-Sentence Welcome</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color:#F7F5F0;border-collapse:collapse;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:56px 48px 24px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#8A7F6E;">Step one of one</td></tr><tr><td class="mw-px mw-title" style="padding:24px 48px 8px 48px;font-family:Georgia,'Times New Roman',serif;font-size:32px;line-height:40px;letter-spacing:-0.01em;color:#1A1A1A;font-weight:400;">Hi {{ first_name }}, here is the one thing to do first in {{ brand_name }}:</td></tr><tr><td class="mw-px mw-title" style="padding:16px 48px 32px 48px;font-family:Georgia,'Times New Roman',serif;font-size:32px;line-height:40px;letter-spacing:-0.01em;color:#1A1A1A;font-weight:400;">{{ one_sentence }}</td></tr><tr><td class="mw-px" style="padding:8px 48px 40px 48px;font-family:Georgia,'Times New Roman',serif;font-size:20px;line-height:32px;color:#1A1A1A;"><a href="{{ one_action_url }}" style="color:#1A1A1A;text-decoration:underline;text-underline-offset:4px;font-weight:600;">Do that one thing now &rarr;</a></td></tr><tr><td class="mw-px" style="padding:8px 48px 40px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:18px;letter-spacing:0.18em;text-transform:uppercase;color:#8A7F6E;">Why this and nothing else &mdash;</td></tr><tr><td class="mw-px" style="padding:0 48px 56px 48px;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#3A3631;">{{ why_this_first }}</td></tr><tr><td class="mw-px" align="center" style="padding:8px 48px 56px 48px;font-family:Georgia,'Times New Roman',serif;font-size:18px;line-height:24px;letter-spacing:0.6em;color:#C9A87A;">*&nbsp;&nbsp;*&nbsp;&nbsp;*</td></tr><tr><td class="mw-px" style="padding:0 48px 8px 48px;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:20px;line-height:30px;color:#1A1A1A;">Yours, no checklist attached,</td></tr><tr><td class="mw-px" style="padding:0 48px 8px 48px;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:20px;line-height:30px;color:#1A1A1A;">{{ sender_name }}</td></tr><tr><td class="mw-px" style="padding:8px 48px 48px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:18px;letter-spacing:0.08em;color:#8A7F6E;">Reply directly: <a href="mailto:{{ reply_to_email }}" style="color:#8A7F6E;text-decoration:underline;">{{ reply_to_email }}</a></td></tr><tr><td class="mw-px" style="padding:0 48px 24px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:18px;line-height:24px;letter-spacing:0.4em;color:#C9A87A;">&mdash;&mdash;&mdash;</td></tr><tr><td class="mw-px" style="padding:0 48px 56px 48px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:18px;letter-spacing:0.12em;text-transform:uppercase;color:#8A7F6E;">You signed up for {{ brand_name }}. One email. No tour. <a href="{{ unsubscribe_url }}" style="color:#8A7F6E;text-decoration:underline;">Unsubscribe</a>.</td></tr></table></body></html>$b$,
         $v$[{"name": "first_name", "label": "First name", "default": "there"}, {"name": "one_sentence", "label": "The one sentence", "default": "Connect your sending domain — everything else can wait."}, {"name": "one_action_url", "label": "Action URL"}, {"name": "why_this_first", "label": "Why this matters", "default": "Without it, even your test sends will land in spam."}]$v$::jsonb),
        -- Negative Welcome
        ('welcome-negative-promise', '97d334abba6c56da13e1c8289ea56262',
         $s$you're in. here's what we won't do.$s$,
         $p$Three promises about what's NOT going to happen in your inbox.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Negative Welcome</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><div style="background-color:#F5F1EA;padding:48px 16px;font-family:Georgia,'Times New Roman',serif;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto;background-color:#FFFFFF;border:1px solid #E6DFD2;border-radius:16px;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:56px 56px 24px 56px;font-family:Georgia,'Times New Roman',serif;"><div style="font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:#8A7F6E;font-weight:600;">A note from {{ sender_name }}</div></td></tr><tr><td class="mw-px" style="padding:0 56px 24px 56px;font-family:Georgia,'Times New Roman',serif;"><h1 class="mw-display" style="margin:0;font-family:Georgia,'Times New Roman',serif;font-size:56px;line-height:60px;letter-spacing:-0.02em;color:#1A1A1A;font-weight:400;text-transform:lowercase;">you&rsquo;re in.</h1><div class="mw-display" style="margin-top:16px;font-family:Georgia,'Times New Roman',serif;font-size:56px;line-height:60px;letter-spacing:-0.02em;color:#B8AC95;font-weight:400;text-transform:lowercase;">here&rsquo;s what we won&rsquo;t do.</div></td></tr><tr><td class="mw-px" style="padding:24px 56px 0 56px;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1A1A1A;">Hi {{ first_name }} &mdash; your <strong style="font-weight:600;">{{ plan_name }}</strong> seat on {{ brand_name }} is active. No setup wizard, no 14-step onboarding email sequence. Just this letter, and the truth.</td></tr><tr><td class="mw-px" align="center" style="padding:40px 56px 32px 56px;font-family:Georgia,'Times New Roman',serif;font-size:14px;letter-spacing:0.5em;color:#B8AC95;">* * *</td></tr><tr><td class="mw-px" style="padding:0 56px 8px 56px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:#8A7F6E;font-weight:600;">Three promises</td></tr><tr><td class="mw-px" style="padding:0 56px 0 56px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td valign="top" width="56" style="padding:24px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;letter-spacing:0.05em;color:#8A7F6E;font-weight:600;">01 /</td><td valign="top" style="padding:24px 0 0 0;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1A1A1A;"><strong style="font-weight:600;">We won&rsquo;t send you a &ldquo;tips &amp; tricks&rdquo; drip.</strong><br /><span style="color:#5C544A;">No five-part course. No &ldquo;day 3 of 7.&rdquo; If we write, it&rsquo;s because something is genuinely new or genuinely useful.</span></td></tr><tr><td valign="top" style="padding:20px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;letter-spacing:0.05em;color:#8A7F6E;font-weight:600;">02 /</td><td valign="top" style="padding:20px 0 0 0;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1A1A1A;"><strong style="font-weight:600;">We won&rsquo;t ask you for a testimonial in week one.</strong><br /><span style="color:#5C544A;">You haven&rsquo;t earned an opinion yet, and we haven&rsquo;t earned one from you. Maybe later. Maybe never. Both are fine.</span></td></tr><tr><td valign="top" style="padding:20px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;letter-spacing:0.05em;color:#8A7F6E;font-weight:600;">03 /</td><td valign="top" style="padding:20px 0 0 0;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1A1A1A;"><strong style="font-weight:600;">We won&rsquo;t pretend this email is from a robot.</strong><br /><span style="color:#5C544A;">Hit reply. It goes to my actual inbox. I read every one, usually within a day, sometimes with typos.</span></td></tr></table></td></tr><tr><td class="mw-px" align="center" style="padding:40px 56px 32px 56px;font-family:Georgia,'Times New Roman',serif;font-size:14px;letter-spacing:0.5em;color:#B8AC95;">* * *</td></tr><tr><td class="mw-px" style="padding:0 56px 12px 56px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:#8A7F6E;font-weight:600;">One thing to do</td></tr><tr><td class="mw-px" style="padding:0 56px 28px 56px;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1A1A1A;">The fastest way to know if {{ brand_name }} is for you is to try the one task that takes ninety seconds. Not a tour. Not a video. The real thing.</td></tr><tr><td class="mw-px" style="padding:0 56px 8px 56px;"><a href="{{ first_action_url }}" style="display:inline-block;background-color:#1A1A1A;color:#FAF9F6;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:15px;font-weight:600;letter-spacing:0.01em;text-decoration:none;padding:14px 28px;border-radius:999px;">Start the 90-second task &rarr;</a></td></tr><tr><td class="mw-px" style="padding:8px 56px 0 56px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;color:#8A7F6E;letter-spacing:0.02em;">~90 sec &middot; no credit card &middot; no signup wall</td></tr><tr><td class="mw-px" align="center" style="padding:48px 56px 32px 56px;font-family:Georgia,'Times New Roman',serif;font-size:14px;letter-spacing:0.5em;color:#B8AC95;">* * *</td></tr><tr><td class="mw-px" style="padding:0 56px 8px 56px;font-family:Georgia,'Times New Roman',serif;font-size:17px;line-height:28px;color:#1A1A1A;font-style:italic;">Glad you&rsquo;re here,</td></tr><tr><td class="mw-px" style="padding:0 56px 4px 56px;font-family:Georgia,'Times New Roman',serif;font-size:24px;line-height:32px;color:#1A1A1A;letter-spacing:-0.01em;">{{ sender_name }}</td></tr><tr><td class="mw-px" style="padding:0 56px 56px 56px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;color:#8A7F6E;">reply &rarr; <a href="mailto:{{ reply_to_email }}" style="color:#8A7F6E;text-decoration:underline;">{{ reply_to_email }}</a></td></tr></table><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="margin:24px auto 0 auto;width:100%;max-width:600px;"><tr><td align="center" style="padding:16px 24px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-size:12px;line-height:20px;color:#8A7F6E;">You&rsquo;re receiving this because you signed up for {{ brand_name }}.<br />Promise #4 (the bonus one): <a href="{{ unsubscribe_url }}" style="color:#8A7F6E;text-decoration:underline;">one-click unsubscribe</a>, always honored.</td></tr></table></div></body></html>$b$,
         $v$[{"name": "first_name", "label": "First name", "default": "there"}, {"name": "plan_name", "label": "Plan", "default": "Starter"}, {"name": "first_action_url", "label": "First task URL"}]$v$::jsonb),
        -- Reply-Bait Welcome
        ('welcome-reply-bait', 'f0aaf3b0a8b923db720d237b2c5832a4',
         $s$Hi {{ first_name }}, one question before anything else$s$,
         $p$Reply with one sentence — that is the entire onboarding.$p$,
         NULL,
         $b$<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Reply-Bait Welcome</title><style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;text-size-adjust:100%;}table{border-collapse:collapse;}img{border:0;max-width:100%;height:auto;}@media only screen and (max-width:620px){.mw-px{padding-left:20px!important;padding-right:20px!important;}.mw-title{font-size:24px!important;line-height:30px!important;}.mw-display{font-size:34px!important;line-height:38px!important;}.mw-hero{font-size:56px!important;line-height:56px!important;}.mw-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box;}.mw-stack-gap{padding:0 0 24px 0!important;}.mw-full{width:100%!important;max-width:100%!important;}.mw-btn{min-width:0!important;}.mw-tight{letter-spacing:0.06em!important;}}</style></head><body style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;"><table role="presentation" width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color:#FAF9F6;width:100%;max-width:600px;"><tr><td class="mw-px" style="padding:80px 56px 24px 56px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.18em;text-transform:uppercase;color:#8A7F6E;">Not automated</td></tr><tr><td class="mw-px" style="padding:24px 56px 8px 56px;font-family:Georgia,'Times New Roman',serif;font-size:15px;line-height:22px;color:#5C5346;">Hi {{ first_name }},</td></tr><tr><td class="mw-px" style="padding:8px 56px 80px 56px;font-family:Georgia,'Times New Roman',serif;font-size:26px;line-height:36px;color:#1A1A1A;font-weight:400;">{{ one_question }}</td></tr><tr><td class="mw-px" style="padding:0 56px 8px 56px;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:17px;line-height:24px;color:#1A1A1A;">Yours, {{ sender_name }}</td></tr><tr><td class="mw-px" style="padding:0 56px 80px 56px;font-family:Georgia,'Times New Roman',serif;font-size:13px;line-height:20px;color:#5C5346;">&mdash; I read every reply.</td></tr><tr><td class="mw-px" style="padding:0 56px 80px 56px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;"><tr><td style="border:1px dotted #C9A87A;padding:18px 22px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;line-height:18px;color:#5C5346;">Reply to: <a href="mailto:{{ reply_to_email }}" style="color:#1A1A1A;text-decoration:none;">{{ reply_to_email }}</a></td></tr></table></td></tr><tr><td class="mw-px" style="padding:0 56px 16px 56px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:18px;letter-spacing:0.08em;color:#8A7F6E;">&mdash; &mdash; &mdash;</td></tr><tr><td class="mw-px" style="padding:0 56px 56px 56px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:18px;color:#8A7F6E;">Sent from {{ brand_name }}. Not what you signed up for? <a href="{{ unsubscribe_url }}" style="color:#8A7F6E;text-decoration:underline;">Unsubscribe</a>.</td></tr></table></body></html>$b$,
         $v$[{"name": "first_name", "label": "First name", "default": "there"}, {"name": "one_question", "label": "The question", "default": "What is the one thing you hope we can help with this month?"}]$v$::jsonb)
)
UPDATE campaign_templates AS template
   SET subject = replacement.subject,
       preview_text = replacement.preview_text,
       description = COALESCE(replacement.description, template.description),
       body_html = replacement.body_html,
       body_mjml = '',
       variables = replacement.variables
  FROM replacement
 WHERE template.tenant_id IS NULL
   AND template.slug = replacement.slug
   AND md5(template.body_html) = replacement.previous_body_md5;

DO $check$
DECLARE
    diverged text;
BEGIN
    SELECT string_agg(template.slug, ', ' ORDER BY template.slug)
      INTO diverged
      FROM campaign_templates AS template
      JOIN (VALUES
          ('announcement-milestone-typographic', 'eeac364c0c135d6a05ba1a8f2121f27e'),
          ('announcement-product-launch', 'b9c76343cd8932b8a363e0373e58ab8d'),
          ('announcement-sunset-with-runway', '736231dd09172b413dbdac3f380d8c69'),
          ('announcement-we-didnt-ship', 'ab7c2f5e4134ef91d6c4903a7730d706'),
          ('automation-anomaly-with-reasoning', 'e498c26b16347f63d1eacf303fc7beb6'),
          ('automation-day-three-tip', 'a8529ae708357d1c2c03fe8dd2154c4c'),
          ('automation-milestone-cohort-hit', '0d48cd6992644c48b27612c9237f42e1'),
          ('automation-post-send-debrief', '353757aefb60fe0b44ff603c4bc4ab62'),
          ('newsletter-card-grid-digest', 'e8ff9702d9d8b2c21362684ccf437e6a'),
          ('newsletter-editorial-masthead', '70dde1451d24788bb7d3997430ffe024'),
          ('newsletter-margin-notes', 'c19db79c322631259a38eca0cbd82efd'),
          ('newsletter-one-link', '010047784e28937c4ea93ef98636b271'),
          ('newsletter-weekly', '5934dea7af1d21609841149c9cddb55d'),
          ('promotional-flash-sale', 'dad48ca4f588112b49fb9a5b661a2350'),
          ('promotional-gradient-bold', '95ad47f5ce32c0017f7504840de31c68'),
          ('promotional-honest-math', '78d89ebdd92c293f33bf3a531ba3e0cb'),
          ('promotional-loyalty-no-coupon', '668c7b0b91ab9cdd8262d98aa7a3a7a1'),
          ('re-engagement-gentle', 'ae25c99e4ef119c08d01f227b4058877'),
          ('re-engagement-letter-from-future-self', '4271cc829a33a68714dab3147e587ac3'),
          ('re-engagement-pause-choice', 'ec25b54289590ece4093f97ff064aaf3'),
          ('transactional-export-ready', 'b889999d3a7e67a4cf8d5d600d6511f3'),
          ('transactional-magic-link-mono-code', '6d9debf8619363fee035563711f237ca'),
          ('transactional-password-reset-timed', 'dd9bfef30773eabc75b33778b428f746'),
          ('transactional-receipt', '692f4a9bbd0db2b438d800ca14cb550a'),
          ('transactional-security-new-device', '9fd561569011ff6d12c8b3e75568544b'),
          ('welcome-day-one-cohort', 'd7b9a122b21fa460256a13527b9e83c4'),
          ('welcome-launch', '2b1c0532e27bf8c40c7f9a68feb91983'),
          ('welcome-negative-promise', 'cd241b54bcdc0a4c5ce9fa618f4ac85c'),
          ('welcome-reply-bait', '934ec52aa9fb73880aaafffc75462ef9')
      ) AS expected (slug, body_md5)
        ON expected.slug = template.slug
     WHERE template.tenant_id IS NULL
       AND md5(template.body_html) <> expected.body_md5;
    IF diverged IS NOT NULL THEN
        RAISE EXCEPTION 'built-in campaign templates were edited after seeding and were not rewritten: %', diverged
            USING HINT = 'Reconcile these platform rows with migrations 0240, 0241 and 1722, then apply 2055.';
    END IF;
END
$check$;

COMMIT;
